def _open_note_dialog(self):
    name = self._get_selected_report_client()
    if not name:
        from tkinter import messagebox
        messagebox.showwarning('Notes', 'Select a client in the Reports list first.')
        return
    default_date = ""
    try:
        default_date = self.end_date_var.get().strip()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0204', 'suppressed exception excpass_0204', __spina_exc)
        pass
    client_uid = None
    person_uid = None
    try:
        if hasattr(self, "db") and getattr(self, "db", None):
            meta = self.db.get_client_link_meta(name, loan_type=self._mode_filter())
            if meta:
                client_uid = (meta.get("client_uid") or "").strip() or None
                person_uid = (meta.get("person_uid") or "").strip() or None
    except Exception as _e:
        try:
            _log_exc("notes:fetch_link_meta", _e)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0205', 'suppressed exception excpass_0205', __spina_exc)
            pass
    NoteEditorDialog(self.root, name, default_date=default_date, loan_type=self._mode_filter(), client_uid=client_uid, person_uid=person_uid)
